\"\"\"Minimal standard-library-only client for the OpenAI Responses API.

Sends private text prompts to the Responses API endpoint using only the
Python standard library (urllib, json). No third-party packages required.

Environment:
    OPENAI_API_KEY  Required. Your OpenAI secret API key.

Usage as a module:
    from openai_client import send_prompt, ResponsesClient
    result = send_prompt(\"Translate 'hello' to French.\")

Usage from the command line:
    OPENAI_API_KEY=sk-... python3 openai_client.py \"Your text prompt here\"
\"\"\"

import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_MODEL = \"gpt-4o-mini\"
DEFAULT_ENDPOINT = \"https://api.openai.com/v1/responses\"
DEFAULT_TIMEOUT = 60  # seconds


class ResponsesError(Exception):
    \"\"\"Raised when the Responses API request fails.\"\"\"


class ResponsesClient:
    \"\"\"A thin standard-library wrapper around the Responses API.\"\"\"

    def __init__(
        self,
        api_key=None,
        model=DEFAULT_MODEL,
        endpoint=DEFAULT_ENDPOINT,
        timeout=DEFAULT_TIMEOUT,
    ):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ResponsesError(
                \"Missing API key: set OPENAI_API_KEY or pass api_key=...\"
            )
        self.model = model
        self.endpoint = endpoint
        self.timeout = timeout

    def send(self, prompt, model=None, timeout=None, **params):
        \"\"\"Send a text prompt to the Responses API and return parsed JSON.

        Extra keyword arguments are forwarded as top-level fields of the
        request body (for example temperature=0.2 or max_output_tokens=512).
        \"\"\"
        if not isinstance(prompt, str) or not prompt.strip():
            raise ResponsesError(\"prompt must be a non-empty string\")

        body = {
            \"model\": model or self.model,
            \"input\": prompt,
        }
        body.update(params)
        payload = json.dumps(body).encode(\"utf-8\")

        request = urllib.request.Request(
            self.endpoint,
            data=payload,
            method=\"POST\",
        )
        request.add_header(\"Authorization\", \"Bearer {}\".format(self.api_key))
        request.add_header(\"Content-Type\", \"application/json\")
        request.add_header(\"Accept\", \"application/json\")

        try:
            with urllib.request.urlopen(
                request, timeout=timeout or self.timeout
            ) as response:
                raw = response.read().decode(\"utf-8\")
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode(\"utf-8\", \"replace\")
            raise ResponsesError(
                \"HTTP {} from Responses API: {}\".format(exc.code, detail)
            ) from exc
        except urllib.error.URLError as exc:
            raise ResponsesError(
                \"Network error contacting Responses API: {}\".format(exc.reason)
            ) from exc

        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ResponsesError(
                \"Could not parse JSON response: {}\".format(raw)
            ) from exc

    @staticmethod
    def extract_text(response):
        \"\"\"Return the concatenated text output from a Responses API result.

        The Responses API returns an "'`output` list of message items, each with
        a `content` list of parts. Text parts carry the model'"'s text.
        \"\"\"
        chunks = []
        for item in response.get(\"output\", []):
            if not isinstance(item, dict):
                continue
            for part in item.get(\"content\", []):
                if isinstance(part, dict) and part.get(\"type\") == \"output_text\":
                    chunks.append(part.get(\"text\", \"\"))
        return \"\".join(chunks)


def send_prompt(prompt, model=None, api_key=None, **params):
    \"\"\"Convenience wrapper: build a client and send a single prompt.\"\"\"
    client = ResponsesClient(api_key=[REDACTED_SECRET] model=model)
    return client.send(prompt, **params)


def _main(argv):
    if len(argv) < 2 or not argv[1].strip():
        print(\"Usage: python3 openai_client.py \\\"your text prompt\\\"\", file=sys.stderr)
        return 2
    prompt = argv[1]
    try:
        result = send_prompt(prompt)
    except ResponsesError as exc:
        print(\"Error: {}\".format(exc), file=sys.stderr)
        return 1
    text = ResponsesClient.extract_text(result)
    print(text or json.dumps(result, indent=2))
    return 0


if __name__ == \"__main__\":
    sys.exit(_main(sys.argv))
PYEOF
